      function BeforeReport return boolean is
begin


  --                                                          CG$DF0001.WN..PRINT_SUSPENSION_INFORMATION.

SELECT BUS_ID INTO :P_BUS_ID 
                     FROM IMPORTERS WHERE ((IMPR_NBR =:PIMPR_NBR  AND  PORT_CD =:PPORT_CD ) OR HQ_IMPR_NBR =:PHQ_IMPR_NBR) AND ROWNUM<=1;
IF :P_CURR_PORT_CD IS NULL THEN :P_CURR_PORT_CD := 99; END IF;

SRW.DO_SQL('alter session set NLS_DATE_FORMAT=''YYYY/MM/DD HH24:MI:SS''');
  --                                                          CG$DF0001.WN..PRINT_SUSPENSION_INFORMATION.

return(TRUE);
end;

      function CG$SuppressFrame (num_recs in Number) return boolean is
-- TEMPLATE DERIVED CODE
begin
  return(num_recs > 0);
end;

