function V_PORT_NAME_SEC1FormatTrigger return boolean is
V_NAME VARCHAR2(100);
BEGIN
	IF :PPORT_CD = 99 THEN
	RETURN(TRUE);
	ELSE

  SELECT PORT_NAME
  INTO   V_NAME
  FROM   SD_PORTS
  WHERE  PORT_CD = :PPORT_CD ;
  SRW.SET_FIELD_CHAR(0,V_NAME);	
 	RETURN(TRUE);
 END IF;
EXCEPTION 
	WHEN NO_DATA_FOUND THEN
--RETURN(NULL);
	RETURN(TRUE);


	RETURN(TRUE);
END;

