      function CF_X1Formula return Char is
X_PORT_NAME VARCHAR2(100);
begin
  SELECT PORT_NAME 
  INTO   X_PORT_NAME
  FROM   SD_PORTS
  WHERE  PORT_CD = :PORT_CD_F1 ;
    RETURN X_PORT_NAME;
EXCEPTION 
	WHEN NO_DATA_FOUND THEN 
	RETURN 'جميع الجمارك';
end;

