      function impr_name_dumFormula return Char is
dummy varchar2(150);
begin
	IF :PORT_F0 = 0 THEN
--IF :IMPR_NBR_F1 IS NULL OR :IMPR_NBR_F1 = 0 THEN 
  	select ARBC_IMPR_NAME into dummy from importers where BUS_ID=:P_BUS_ID AND ROWNUM<=1 AND ARBC_IMPR_NAME IS NOT NULL;
	ELSE
  	select ARBC_IMPR_NAME into dummy 
  	from importers 
  	where PORT_CD = :PORT_CD_F1 AND IMPR_NBR = :IMPR_NBR_F1;
	END IF;
  RETURN DUMMY;
EXCEPTION WHEN OTHERS THEN 
	RETURN NULL;
end;

